<?php

namespace App\Services;

use App\Models\Admin;
use App\Models\OrderApiCredential;
use App\Models\SalesOrder;
use App\Models\Team;
use App\Models\User;
use Illuminate\Support\Facades\DB;
use Throwable;

/**
 * Order-scoped API key delivery.
 *
 * Unlike {@see ApiKeyService} (one provider credential for the deployment),
 * this stores *the customer's own key* against a specific order, as part of
 * order fulfillment. The key is entered manually — it is never generated by
 * LeadX — and there is deliberately no provider name, base URL or model
 * name: only the key, tied to its order.
 *
 * Security posture:
 * - The key is stored Laravel-encrypted (the model's `encrypted` cast); the
 *   database only ever holds ciphertext.
 * - This service is the only place the plaintext exists at runtime.
 *   `status()` returns a masked indicator + who/when, never the key.
 * - `reveal()` is the sole plaintext read path and is gated by
 *   {@see canManage()}: an unauthorized team member or employee gets no
 *   access at all, and a failed reveal is a no-op (the value is not logged).
 * - Every store/replace re-stamps who did it and when; an audit row records
 *   the event with a *masked* indicator only — the plaintext key is never
 *   written to audit_logs, application logs, or a notification payload.
 */
class OrderCredentialService
{
    /**
     * Store or replace the customer's API key for an order, recording the
     * actor. Returns the credential. A failed write leaves the previous key
     * intact (the save is transactional), matching the provider-credential
     * behaviour.
     *
     * @return array{credential: ?OrderApiCredential, saved: bool, message: string}
     */
    public function store(SalesOrder $order, string $plainKey, mixed $actor, ?string $ip = null): array
    {
        $plainKey = trim($plainKey);

        if ($plainKey === '') {
            return ['credential' => null, 'saved' => false, 'message' => 'The API key may not be blank.'];
        }

        $credential = OrderApiCredential::firstOrNew(['order_id' => $order->id]);
        $credential->key = $plainKey; // the encrypted cast handles the cipher
        $credential->updated_by_id = $actor?->getKey();
        $credential->updated_by_type = $actor ? $actor::class : null;

        try {
            $credential->saveOrFail();
        } catch (Throwable) {
            // Never log the key or the exception body (an Eloquent failure
            // can echo ciphertext back in its SQL).
            report('Order API key save failed for order '.$order->id);

            return ['credential' => null, 'saved' => false, 'message' => 'The API key could not be saved. The previous key remains in effect.'];
        }

        $this->audit($order, $credential, $actor::class ?? null, $ip);

        return ['credential' => $credential, 'saved' => true, 'message' => 'API key saved for order '.$order->order_number.'.'];
    }

    /**
     * Read view: masked indicator + who/when. The full key is never in here.
     *
     * @return array{configured: bool, masked_key: ?string, updated_by_type: ?string, updated_at: ?string}
     */
    public function status(SalesOrder $order): array
    {
        $credential = OrderApiCredential::forOrder($order->id);

        return [
            'configured' => $credential !== null && filled($credential->key),
            'masked_key' => $credential?->maskKey(),
            'updated_by_type' => $credential?->updated_by_type ? class_basename($credential->updated_by_type) : null,
            'updated_at' => $credential?->updated_at?->toIso8601String(),
        ];
    }

    /**
     * The plaintext key for an authorized actor, or null when access is
     * denied or the ciphertext is unusable. The value is never logged.
     */
    public function reveal(SalesOrder $order, mixed $actor): ?string
    {
        if (! $this->canManage($order, $actor)) {
            return null;
        }

        return OrderApiCredential::forOrder($order->id)?->decryptedKey();
    }

    /**
     * Does this order have a stored customer key? Static, so the WhatsApp
     * share service can report whether an opted-in share actually folded a
     * key into its text.
     */
    public static function hasKey(SalesOrder $order): bool
    {
        return OrderApiCredential::hasKeyFor($order->id);
    }

    /**
     * The order's customer key, or null when none is stored or the
     * ciphertext is unusable. Callers must have checked {@see canManage()}
     * and must never log the returned value.
     */
    public static function keyFor(SalesOrder $order): ?string
    {
        return OrderApiCredential::forOrder($order->id)?->decryptedKey();
    }

    /**
     * May this actor view or manage the order's customer key?
     *
     *  - an Admin (super admin) manages any order's key;
     *  - a Team manages the keys of its own team's orders;
     *  - an Employee manages only the keys of orders they are the assigned
     *    employee of, or that belong to their team.
     *
     * Everyone else — other teams' members, unrelated employees — has no
     * access, so a key can never be read cross-team.
     */
    public function canManage(SalesOrder $order, mixed $actor): bool
    {
        if ($actor instanceof Admin) {
            return true;
        }

        if ($actor instanceof Team) {
            return (int) $order->team_id === (int) $actor->id;
        }

        if ($actor instanceof User) {
            $isOwner = (int) ($order->assigned_employee_id ?? 0) === (int) $actor->id;
            $isTeamMember = (int) ($actor->team_id ?? 0) === (int) ($order->team_id ?? 0);

            return $isOwner || $isTeamMember;
        }

        return false;
    }

    /**
     * Audit the write. Only the masked indicator is recorded — the plaintext
     * key is structurally excluded from the payload.
     */
    protected function audit(SalesOrder $order, OrderApiCredential $credential, ?string $actorType, ?string $ip): void
    {
        DB::table('audit_logs')->insert([
            'auditable_type' => $order->getMorphClass(),
            'auditable_id' => $order->id,
            'event' => $credential->created_at === $credential->updated_at
                ? 'order_api_key.stored'
                : 'order_api_key.replaced',
            'new_values' => json_encode([
                'masked_key' => $credential->maskKey(),
                'actor_type' => $actorType,
                'actor_id' => $credential->updated_by_id,
                'at' => now()->toIso8601String(),
            ]),
            'ip' => $ip,
            'created_at' => now(),
            'updated_at' => now(),
        ]);
    }
}
